<style>
.rd{--orange:#f65b05;--ink:#192333;--muted:#6b7789;font:15px/1.6 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}
.rd *{box-sizing:border-box}.rd a{color:var(--orange)}.rd h1{font-size:28px;line-height:1.3;letter-spacing:-.7px;margin:0 0 8px;font-weight:800}.rd h2{font-size:18px;margin:0 0 12px}.rd p{margin:0 0 14px}.rd-muted{color:var(--muted)}.rd-shell{max-width:1400px;padding:32px 24px;margin:auto}.rd-brand{font-size:24px;font-weight:850;letter-spacing:-1px}.rd-brand span{color:var(--orange)}.rd-top{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:28px}.rd-card{padding:26px;background:#fff;border:1px solid #e7e9ee;border-radius:18px;box-shadow:0 4px 18px #19233305;margin-bottom:20px}.rd-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 20px;background:var(--orange);border:0;color:white!important;border-radius:10px;font:inherit;font-weight:700;cursor:pointer;text-decoration:none}.rd-button:hover{background:#db4b00}.rd-button.secondary{background:#fff;color:var(--ink)!important;border:1px solid #d9dee7}.rd label{display:block;font-weight:650;margin-bottom:8px}.rd input,.rd textarea,.rd select{width:100%;padding:12px 14px;border:1px solid #d8dee8;background:#fff;border-radius:10px;font:inherit;color:var(--ink)}.rd input:focus,.rd textarea:focus,.rd select:focus{outline:3px solid #ffedd5;border-color:var(--orange)}.rd-help{font-size:13px;margin-top:8px!important;color:var(--muted)}.rd-error{color:#b42318;background:#fff0ed;padding:12px 16px;border-radius:10px;margin:16px 0}.rd-success{color:#177446;background:#edf9f1;padding:12px 16px;border-radius:10px;margin-bottom:20px}.rd-gate{max-width:460px;margin:72px auto}.rd-lock{display:flex;align-items:center;justify-content:center;width:56px;height:56px;border-radius:16px;background:#fff0e4;color:var(--orange);margin-bottom:24px}.rd-stat{color:#247649;background:#eaf8ee;border-radius:999px;padding:6px 14px;font-size:13px;font-weight:700;display:inline-block}.rd-tools{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0 20px}.rd-tools input{flex:2;min-width:220px}.rd-tools select{flex:1;min-width:180px}.rd-table-wrap{overflow:auto;background:white;border:1px solid #e7e9ee;border-radius:16px}.rd-table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}.rd-table th{background:#f8f9fb;color:#627084;font-size:12px;text-transform:uppercase;letter-spacing:.4px;padding:17px 20px;border-bottom:1px solid #e7e9ee}.rd-table td{padding:17px 20px;border-bottom:1px solid #eef0f4;vertical-align:middle}.rd-table tr:last-child td{border-bottom:0}.rd-table tbody tr:hover{background:#fffaf6}.rd-photo{width:90px;height:56px;object-fit:cover;border:1px solid #e7e9ee;border-radius:7px;display:block;margin-bottom:3px}.rd-small{font-size:12px}.rd-empty{padding:40px!important;text-align:center;color:var(--muted)}.rd-hidden{display:none!important}.rd-room{font-weight:800}.rd-foot{font-size:12px;color:var(--muted);margin-top:20px}.rd-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.rd-link{word-break:break-all;display:block;background:#fff8f2;border:1px solid #ffdfc4;padding:14px 16px;border-radius:10px;margin-bottom:14px}
@media(max-width:640px){.rd-shell{padding:22px 16px}.rd h1{font-size:24px}.rd-card{padding:22px}.rd-gate{margin:32px auto}.rd-table{font-size:13px}.rd-table th,.rd-table td{padding:14px}.rd-top{margin-bottom:20px}}
</style>
